<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);
if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user){Security::destroySession();header('Location: login.php');exit;}if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'settings.manage')){http_response_code(403);exit('Administrator settings permission required.');}}
catch(Throwable $e){error_log('Settings manager: '.$e->getMessage());http_response_code(503);exit('Portal settings are unavailable.');}
$keys=['barangay_name'=>'Official Barangay Name','municipality'=>'Municipality / City','province'=>'Province','mandate'=>'Mandate / Legal Basis','office_address'=>'Official Office Address','office_hotline'=>'Official Hotline','office_email'=>'Official Office Email','office_hours'=>'Office Hours','leadership'=>'Leadership / Officials Reference','dpo_contact'=>'Data Protection Officer Contact','official_domain_status'=>'Official Domain Status','https_status'=>'HTTPS Deployment Status'];$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);$error='Session expired. Refresh and try again.';}
 else try{$db->beginTransaction();foreach($keys as $key=>$label){$value=trim((string)($_POST[$key]??''));if(strlen($value)>2000)throw new InvalidArgumentException($label.' is too long.');$q=$db->prepare('INSERT INTO system_settings (setting_key,setting_value,is_public,updated_by_user_id) VALUES (:key,:value,1,:uid) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by_user_id=VALUES(updated_by_user_id),updated_at=NOW()');$q->execute(['key'=>$key,'value'=>$value,'uid'=>$user['user_id']]);}AuditLogger::record($db,(int)$user['user_id'],'PUBLIC_PORTAL_SETTINGS_UPDATED','system_settings',null,['updated_keys'=>array_keys($keys)]);$db->commit();$message='Public portal information updated.';}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Settings update: '.$e->getMessage());$error='Unable to save portal settings.';}
}
$q=$db->query('SELECT setting_key,setting_value FROM system_settings');$values=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$values[$r['setting_key']]=$r['setting_value'];
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Public Portal Settings','Configure verified agency identity and contact details.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">ADMINISTRATIVE CONTROL</p><h1>Public Portal Settings</h1><p>Replace demonstration placeholders with verified information approved for public release.</p></div></section><section class="section"><div class="notice warning"><b>Verify before publishing</b><p>Do not invent leadership names, official contact details, mandate text, DPO identity, domain status, or HTTPS status. Use only details formally confirmed by the Barangay.</p></div><?php if($message): ?><div class="notice info" role="status"><?= Security::e($message) ?></div><?php endif; ?><?php if($error): ?><div class="notice warning" role="alert"><?= Security::e($error) ?></div><?php endif; ?><form class="portal-form content-panel" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><?php foreach($keys as $key=>$label): ?><label><?= Security::e($label) ?><textarea name="<?= Security::e($key) ?>" rows="<?= in_array($key,['mandate','leadership','dpo_contact','office_address'],true)?3:1 ?>" maxlength="2000"><?= Security::e($values[$key]??'') ?></textarea></label><?php endforeach; ?><button class="auth-submit" type="submit">Save public information</button></form></section></main><?php pageFooter();
